INSERT INTO "classifications" VALUES(60,'claude-haiku-5-5','2026-10-16T15:04:01Z',1,0.85,0,'{"actions_taken": ["Volcanic alert level lowered from Level 3 (restriction on entering mountain) to Level 2 (restriction around crater)", "Evacuation order for Fukiage Onsen lifted"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Sapporo District Meteorological Observatory", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Tokachidake, Hokkaido, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "volcanic", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "北海道・十勝岳の噴火警戒レベル3→2 吹上温泉の「避難指示」解除", "outcome": "not_reported", "outcome_justification": "The item reports the downgrade of the alert level and lifting of evacuation order based on decreased seismic activity; no lives saved or failures in warning delivery are described.", "relevant": true, "review": false, "summary_en": "JMA and the Sapporo District Meteorological Observatory lowered the Tokachidake volcano alert level from 3 (entry restriction) to 2 (crater-area restriction) on 16 October, citing a decline in seismic activity. The change lifted the evacuation order for Fukiage Onsen, a hot spring area near the crater. The item is a short snippet, so details of monitoring data and communication methods are limited.", "summary_original": "気象庁・札幌管区気象台は16日、十勝岳の噴火警戒レベルを3（入山規制）から2（火口周辺規制）に引き下げた。地震活動の低下傾向を受けたもので、吹上温泉の避難指示も解除された。", "title_en": "Hokkaido''s Tokachidake volcano alert level lowered from 3 to 2; evacuation order for Fukiage Onsen lifted", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(75,'claude-haiku-5-5','2026-10-16T15:04:11Z',1,0.9,0,'{"actions_taken": ["NTT Docomo announced the failure of its emergency earthquake alert (Area Mail) system"], "agencies": [{"country": "JP", "name": "NTT Docomo", "type": "other"}, {"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-16", "event_location": null, "event_name": null, "ew4all_pillars": [3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "NTTドコモ、緊急地震速報が配信されず システムに不具合", "outcome": "negative", "outcome_justification": "Docomo subscribers did not receive the JMA earthquake early warning cancellation message via Area Mail because of a system fault, and delivery was expected to remain unavailable for several days until restoration.", "relevant": true, "review": false, "summary_en": "NTT Docomo announced that its Area Mail system failed to deliver the Japan Meteorological Agency''s cancellation of an emergency earthquake warning to its mobile customers. The fault was due to a system problem, and Area Mail delivery was expected to be unavailable for several days until service was restored. This is a warning dissemination failure affecting cell broadcast alerts.", "summary_original": "NTTドコモは、気象庁が取り消した緊急地震速報を伝える「エリアメール」がドコモの携帯電話に配信されなかったと発表した。システム不具合が原因で、復旧までの数日間エリアメールが届かない見込みだ。", "title_en": "NTT Docomo: earthquake early warning not delivered due to system fault", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(101,'claude-haiku-5-5','2026-10-16T15:04:36Z',1,0.6,0,'{"actions_taken": ["Revision of the Patricova flood-risk planning framework prohibiting underground garages in highest flood-risk zones", "Reinforcement of sewer systems and street paving in flood-prone areas", "Building design measures such as evacuation stairs on ground floors and elevators on upper floors"], "agencies": [{"country": "ES", "name": "Patricova", "type": "other_national_agency"}], "confidence": 0.6, "countries": ["ES"], "dissemination_channels": [], "event_date": null, "event_location": "Valencia, Spain", "event_name": null, "ew4all_pillars": [1, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Así se construirá tras la dana: comercios con poco aforo, escaleras de evacuación en bajos y ascensores en pisos altos", "outcome": "not_reported", "outcome_justification": "The item describes planned post-flood building and planning regulations rather than the performance of any warning during an event.", "relevant": true, "review": false, "summary_en": "Following the DANA (cut-off low) floods in Valencia, the revised Patricova planning rules ban underground garages in the highest flood-risk zones and strengthen sewers and pavements. The changes also include evacuation stairs on ground floors and elevators on upper floors in new buildings. The item focuses on risk-reduction and preparedness measures rather than on warnings issued during the event.", "summary_original": "La revisión del Patricova prohíbe los garajes subterráneos en las zonas de mayor riesgo de inundación y refuerza el alcantarillado y el pavimento de las calles. Tras la DANA, se proyectan edificios con escaleras de evacuación en plantas bajas y ascensores en pisos altos.", "title_en": "This is how it will be built after the DANA: shops with low occupancy, evacuation stairs on ground floors and elevators on upper floors", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(103,'claude-haiku-5-5','2026-10-16T15:05:10Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "INA (Instituto Nacional del Agua)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-10-16", "event_location": "Santa Fe, Corrientes and Entre Ríos, Argentina", "event_name": null, "ew4all_pillars": [2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del río Paraná: cuándo se espera el pico y qué pasará en Santa Fe, Corrientes y Entre Ríos", "outcome": "not_reported", "outcome_justification": "The snippet reports an advancing river wave complicating coastal localities and expert warnings about El Niño impacts, but does not describe actual warning outcomes.", "relevant": true, "review": false, "summary_en": "A flood wave on the Paraná River is complicating several coastal localities in Santa Fe, Corrientes and Entre Ríos, with the crest timing a subject of forecasting. Specialists also warn about the impact of El Niño on the coming summer, indicating monitoring and forecast communication.", "summary_original": "El avance de la onda fluvial del río Paraná complica a diversas localidades costeras de Santa Fe, Corrientes y Entre Ríos, mientras especialistas advierten sobre el impacto de El Niño para el próximo verano.", "title_en": "Paraná River flood: when the crest is expected and what will happen in Santa Fe, Corrientes and Entre Ríos", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(104,'claude-haiku-5-5','2026-10-16T15:04:43Z',1,0.8,0,'{"actions_taken": ["Evacuation of 19 people due to river rise"], "agencies": [{"country": "AR", "name": "Yacyretá", "type": "other"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Misiones, Argentina", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 19, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Misiones: continúa la alerta por El Niño y evacuaron a 19 personas por la crecida de ríos", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and a forecast of partial relief with possible new peaks, but does not state whether warnings led to measurable lives saved or shortcomings.", "relevant": true, "review": false, "summary_en": "Yacyretá anticipated partial relief from river levels starting Saturday but warned that new peaks could occur during the October–December quarter linked to El Niño. Nineteen people were evacuated in Misiones due to river flooding. The item reflects forecasting and advisory communication alongside response actions.", "summary_original": "Yacyretá anticipó un alivio parcial a partir del sábado, aunque advirtió que durante el trimestre octubre-diciembre podrían verificarse nuevos picos. Se evacuaron 19 personas por la crecida de ríos en Misiones.", "title_en": "Misiones: alert continues over El Niño and 19 people evacuated due to river flooding", "wmo_regions": ["III"]}');
