INSERT INTO "classifications" VALUES(136,'claude-haiku-5-5','2026-10-16T15:06:33Z',1,0.8,0,'{"actions_taken": ["Workshops with neighbourhood associations", "Designation of evacuation points in high ground", "Deployment of mobile tent system", "Planned evacuations in Bajada Grande"], "agencies": [{"country": "AR", "name": "Municipality of Paraná (Secretaría de Desarrollo Humano)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["other"], "event_date": "2026-10-15", "event_location": "Paraná, Entre Ríos, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "end of month (approx. 2 weeks ahead)", "lead_time_hours": null, "original_title": "Fenómeno de El Niño: Paraná se prepara con carpas móviles y prevé evacuaciones en Bajada Grande a fin de mes", "outcome": "not_reported", "outcome_justification": "The item describes preparations and planned evacuations ahead of the river rise; no outcome has yet been reported.", "relevant": true, "review": false, "summary_en": "The Municipality of Paraná is preparing for an expected Paraná River rise linked to El Niño, with community workshops, designated high-ground evacuation points, and a mobile tent system. Evacuations in Bajada Grande are planned for the end of the month. The official also warned about the growing number of people experiencing homelessness.", "summary_original": "El Municipio de Paraná se prepara ante la crecida del río Paraná con talleres con vecinales, puntos de evacuación en zonas altas, un sistema de carpas móviles y evacuaciones previstas en Bajada Grande a fin de mes.", "title_en": "El Niño phenomenon: Paraná prepares with mobile tents and plans evacuations in Bajada Grande at month''s end", "wmo_regions": ["III"]}');
