INSERT INTO "classifications" VALUES(1067,'claude-haiku-5-5','2026-10-17T07:47:15Z',1,0.93,0,'{"actions_taken": ["JMA issued forecast of intensification into a very strong typhoon", "JMA called on the public to stay informed about future information"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-17", "event_location": null, "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "Next week''s track forecast (approx. 5-7 days ahead, as implied)", "lead_time_hours": null, "original_title": "台風30号 非常に強い勢力に発達する見込み 今後の情報に注意", "outcome": "not_reported", "outcome_justification": "The item reports a forecast and advisory only; no impacts or outcomes of the warning are described yet.", "relevant": true, "review": false, "summary_en": "Typhoon No. 30 is moving westward over the sea far southeast of Japan and is forecast to intensify into a very strong typhoon. The track forecast for next week has a wide range of uncertainty, and the Japan Meteorological Agency has urged the public to keep following the latest information.", "summary_original": "強い台風30号は、日本のはるか南東の海上を西寄りに進んでおり、今後非常に強い勢力に発達する見込みです。来週の進路予想には幅があり、気象庁は今後の情報に注意するよう呼びかけています。", "title_en": "Typhoon No. 30 expected to develop into a very strong typhoon; public urged to stay informed", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1079,'claude-haiku-5-5','2026-10-17T07:46:51Z',1,0.93,0,'{"actions_taken": ["JMA investigating the cause of erroneous earthquake early warnings", "JMA identified use of data from distant observation stations that should not have been used"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Hokkaido to Tokai region, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "緊急地震速報の過大推定 過去の対策が機能せず 気象庁は調査", "outcome": "negative", "outcome_justification": "Earthquake early warnings were erroneously issued over a wide area from Hokkaido to Tokai due to overestimation, and previous countermeasures did not prevent the error.", "relevant": true, "review": false, "summary_en": "On 16 October, JMA erroneously issued earthquake early warnings across a wide area from Hokkaido to the Tokai region. JMA has revealed that data from distant observation stations, which should not have been used, were mistakenly included, causing overestimation of the earthquake. Past countermeasures reportedly did not function, and JMA is investigating.", "summary_original": "16日、北海道から東海にかけての広い範囲で緊急地震速報を誤って発表したことについて、気象庁は、本来使われないはずの、震源から遠く離れた観測点のデータを使うミスが起きていたと明らかにしました。過大に推定された原因を調査しています。", "title_en": "Overestimation of earthquake early warnings; past countermeasures failed to work, JMA investigating", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(1126,'claude-haiku-5-5','2026-10-17T07:47:25Z',0,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Ministry of Health, Labour and Welfare", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "避難所の補助犬同伴 、 国が対応強化へ 「 想定 」 自治体は1割", "outcome": "not_reported", "outcome_justification": "The item concerns shelter accommodation policy for assistance dogs during disasters, not the monitoring, forecasting, warning or dissemination of any specific hazard.", "relevant": false, "review": false, "summary_en": "Japan''s Ministry of Health, Labour and Welfare surveyed municipalities on how they would accept assistance dogs at evacuation shelters during disasters, finding only about 10% have concrete plans. The article addresses shelter preparedness for people with disabilities rather than early warning services for a hazard.", "summary_original": "厚生労働省が全国の市町村に災害時の補助犬の受け入れ態勢を尋ねたところ、具体的な対応を想定している自治体は約1割にとどまることが判明した。", "title_en": "Shelters to accommodate assistance dogs: national government to strengthen response; only 10% of municipalities have planned for it", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1127,'claude-haiku-5-5','2026-10-17T07:47:28Z',0,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "「 特集 」 防災庁設置を日本の未来共創につなげる本気の事前防災を", "outcome": "not_reported", "outcome_justification": "The snippet is a feature on institutional disaster-prevention policy and a past earthquake; it does not describe any warning, forecast, or monitoring during an event.", "relevant": false, "review": false, "summary_en": "A Kyodo feature discusses the planned launch of Japan''s Disaster Prevention Agency and refers to the 2016 Kumamoto earthquake and an active fault in the area. The snippet contains no information on warnings, forecasts or dissemination during hazard events.", "summary_original": "災害対策の司令塔機能を担う防災庁の発足や熊本地震に言及する特集記事で、早期警戒の具体的な運用に関する記述は確認できない。", "title_en": "[Feature] Turning the establishment of the Disaster Prevention Agency into a serious proactive disaster prevention for Japan''s future", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1128,'claude-haiku-5-5','2026-10-17T07:47:18Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japanese government", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "「 ペットと一緒に避難所 」 の理想と現実 … 熊本地震や千葉豪雨では利用を断られたり苦情も ： 東京新聞デジタル", "outcome": "not_reported", "outcome_justification": "The item concerns policy on evacuating pets after disasters and shelter acceptance, not the monitoring, forecasting, warning or dissemination of hazards.", "relevant": false, "review": false, "summary_en": "The article reports that the Japanese government extended revisions to its guidelines on evacuating pets during disasters, following the Kumamoto earthquake and Chiba floods, where some evacuees were refused use of shelters with pets or faced complaints. It concerns shelter and evacuation policy rather than early warning services.", "summary_original": "国は、今夏の熊本地震や千葉豪雨などを受け、災害時のペットの避難に関する指針の改定作業を「延長」した。指針では、ペットと一緒に行動する「同行避難」などが示されている。", "title_en": "The ideal and reality of evacuating with pets to shelters: pet-use refusals and complaints after the Kumamoto earthquake and Chiba floods", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1129,'claude-haiku-5-5','2026-10-17T07:46:44Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Fukushima Television", "type": "media"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Fukushima, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "防災気象情報が新運用から5カ月 河川警報と線状降水帯予測に新制度 自治体は対応に課題（福島テレビ） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The snippet describes changes to the warning system and municipal difficulties in responding, but reports no specific event outcome.", "relevant": true, "review": false, "summary_en": "Since May 2026, Japan''s disaster weather information has been operated under a new system, introducing evacuation-level calls such as Level 3 and Level 4, river warning targets, and short-term forecasts of linear rainbands. Municipalities report difficulties in deciding how to respond to the changes.", "summary_original": "2026年5月から防災気象情報の運用が変わり、避難の判断に使われる「レベル3」「レベル4」などの新しい呼びかけが始まった。河川の警報対象や線状降水帯の直前予測など仕組みが大きく変わる中、自治体では対応に悩む声も出ている。", "title_en": "Five months after new disaster weather information operations began: new river warning and linear rainband forecast system; municipalities face challenges in responding (Fukushima TV)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1130,'claude-haiku-5-5','2026-10-17T07:46:54Z',1,0.95,0,'{"actions_taken": ["Senapred declared a Preventive Early Alert for the Metropolitan Region", "DMC issued an advisory for probable thunderstorms in seven regions between 19 and 20 October"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Dirección Meteorológica de Chile (DMC)", "type": "NMHS"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": ["other"], "event_date": "2026-10-19", "event_location": "Región Metropolitana, Chile", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "about 2 days before the frontal system arrives (Monday 19 to Wednesday 21 October)", "lead_time_hours": 48, "original_title": "Alerta Temprana Preventiva para la Región Metropolitana: Se esperan tormentas eléctricas con granizos - Meganoticias", "outcome": "not_reported", "outcome_justification": "The item only reports forecasts and alerts issued; no observed outcomes are given.", "relevant": true, "review": false, "summary_en": "Senapred declared a Preventive Early Alert for the Santiago Metropolitan Region ahead of a new frontal system expected Monday and active until Wednesday, bringing possible thunderstorms with hail. The Dirección Meteorológica de Chile issued an advisory for probable thunderstorms in seven regions between 19 and 20 October.", "summary_original": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana por el pronóstico de un nuevo sistema frontal que ingresaría el lunes y se mantendría activo hasta el miércoles. La DMC emitió un aviso por probables tormentas eléctricas en siete regiones entre el lunes 19 y el martes 20 de octubre.", "title_en": "Preventive Early Alert for the Metropolitan Region: Thunderstorms with Hail Expected", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1131,'claude-haiku-5-5','2026-10-17T07:47:02Z',1,0.85,0,'{"actions_taken": ["Declaration of a Red Alert for the Metropolitan Region", "Suspension of classes in more than 100 establishments", "Closure of Metro stations"], "agencies": [{"country": "CL", "name": "Government of Chile (Ministry of Interior/Emergency authorities, minister Ximena Rincón)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-13", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Ministra Rincón confirma fin de la Alerta Roja tras las fuertes lluvias en la Región Metropolitana", "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert being lifted and the disruptions caused, but does not state whether the warning led to lives saved or reduced losses, nor whether it was received or acted upon.", "relevant": true, "review": false, "summary_en": "Chile''s government confirmed the end of a Red Alert declared for the Metropolitan Region due to heavy rains that caused flooding, Metro station closures and suspension of classes in over 100 schools. The minister warned there were no certain indicators that the bad weather would end, so the alert status reflects an ongoing hazard assessment.", "summary_original": "La ministra Ximena Rincón confirmó el fin de la Alerta Roja por fuertes lluvias que causaron anegamientos, cierres del Metro y suspensión de clases en más de 100 establecimientos en la Región Metropolitana.", "title_en": "Minister Rincón confirms end of Red Alert after heavy rains in the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1132,'claude-haiku-5-5','2026-10-17T07:47:06Z',1,0.95,0,'{"actions_taken": ["SMN forecast intensification and approach of Category 3 hurricane to Jalisco coast", "Protección Civil set green alert for 22 localities with low danger as a preventive measure"], "agencies": [{"country": "MX", "name": "Servicio Meteorológico Nacional (SMN)", "type": "NMHS"}, {"country": "MX", "name": "Protección Civil de Jalisco", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["MX"], "dissemination_channels": ["other"], "event_date": "2026-10-18", "event_location": "Jalisco, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [2, 3, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Approximately 1 day before expected closest approach to the Jalisco coast (early Sunday, 18 October)", "lead_time_hours": 24, "original_title": "Huracán \"Trudy\" de categoría 3 enciende alerta en 93 municipios de Jalisco", "outcome": "not_reported", "outcome_justification": "The item reports forecasts and preventive alerts issued before the event; no outcome is reported yet.", "relevant": true, "review": false, "summary_en": "Mexico''s National Meteorological Service forecasts that Category 3 Hurricane Trudy will intensify and approach the Jalisco coast early on 18 October. Civil Protection has set a preventive green alert for 22 low-danger localities, covering 93 municipalities in total.", "summary_original": "El SMN prevé que el huracán Trudy, de categoría 3, se intensifique y se acerque a las costas de Jalisco la madrugada del domingo 18 de octubre. Protección Civil estableció alerta verde para 22 localidades con peligro bajo, como medida preventiva.", "title_en": "Category 3 Hurricane \"Trudy\" triggers alert in 93 municipalities of Jalisco", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1133,'claude-haiku-5-5','2026-10-17T07:46:48Z',1,0.95,0,'{"actions_taken": ["Senapred declared Preventive Early Alert for the Metropolitan Region in coordination with the regional presidential delegation"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Delegación Presidencial Regional Metropolitana", "type": "other_national_agency"}, {"country": "CL", "name": "Dirección Meteorológica de Chile (DMC)", "type": "NMHS"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Warning issued 2-3 days before forecast precipitation (Tuesday 20 to Wednesday 21 October)", "lead_time_hours": 60, "original_title": "Pronóstico de lluvias, granizo y tormentas eléctricas en Santiago: Senapred declara Alerta Temprana Preventiva en la Región Metropolitana", "outcome": "not_reported", "outcome_justification": "The item reports the forecast and preventive alert declaration only; no outcome of the event is given.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency service Senapred declared a Preventive Early Alert for the Metropolitan Region based on a DMC forecast of normal to moderate rain, hail and thunderstorms expected between 20 and 21 October. The alert was declared in coordination with the regional presidential delegation ahead of the forecast event.", "summary_original": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana por el pronóstico de lluvias, granizo y tormentas eléctricas previstas entre el martes 20 y el miércoles 21 de octubre, en coordinación con la Delegación Presidencial. La DMC emitió un aviso por precipitaciones normales a moderadas.", "title_en": "Forecast of rain, hail and thunderstorms in Santiago: Senapred declares Preventive Early Alert in the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1348,'claude-haiku-5-5','2026-10-17T09:49:38Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs", "type": "international"}], "confidence": 0.8, "countries": ["CL", "HT", "MX", "PA"], "dissemination_channels": ["other"], "event_date": "2026-10-16", "event_location": null, "event_name": null, "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": "Forecast strengthening into Category 4 hurricane before passing off Michoacán and Colima coasts this weekend", "lead_time_hours": null, "original_title": "Panama: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "outcome": "not_reported", "outcome_justification": "Snippet reports hurricane forecast and earthquake/severe weather impacts but does not describe warning effectiveness or actions taken.", "relevant": true, "review": false, "summary_en": "OCHA''s weekly update reports a forecast that tropical storm Trudy will strengthen into a Category 4 hurricane off the coasts of Michoacán and Colima, Mexico, following a series of storms tracking north-west along the coast. It also reports 36,000 people without power after severe weather in Chile and 3,600 people in shelters after a magnitude 7.5 earthquake in Panama, with 4,000 homes damaged.", "summary_original": null, "title_en": "Panama: Latin America & The Caribbean Weekly Situation Update as of 16 October 2026", "wmo_regions": ["III", "IV"]}');
