INSERT INTO "stories" VALUES(39,'flood|ES|valencia','flood','2026-10-16T15:43:32Z','2026-10-16T14:52:35Z','2026-10-16','{"actions": ["Revision of the Patricova flood-risk planning framework prohibiting underground garages in highest flood-risk zones", "Reinforcement of sewer systems and street paving in flood-prone areas", "Building design measures such as evacuation stairs on ground floors and elevators on upper floors"], "agencies": [{"country": "ES", "name": "Patricova", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.6, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-10-16", "event_location": "Valencia, Spain", "event_name": null, "first_seen": "2026-10-16T14:52:35Z", "hazard": "flood", "hazards": ["flood"], "id": 39, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-16T14:52:35Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes planned post-flood building and planning regulations rather than the performance of any warning during an event.", "pillars": [1, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-16T13:45:00Z", "source_name": "lasprovincias.es", "title": "Así se construirá tras la dana: comercios con poco aforo, escaleras de evacuación en bajos y ascensores en pisos altos", "title_en": "This is how it will be built after the DANA: shops with low occupancy, evacuation stairs on ground floors and elevators on upper floors", "url": "https://www.lasprovincias.es/comunitat/construira-tras-dana-comercios-poco-aforo-escaleras-20261016142757-nt.html"}], "summaries_original": {"es": "La revisión del Patricova prohíbe los garajes subterráneos en las zonas de mayor riesgo de inundación y refuerza el alcantarillado y el pavimento de las calles. Tras la DANA, se proyectan edificios con escaleras de evacuación en plantas bajas y ascensores en pisos altos."}, "summary_en": "Following the DANA (cut-off low) floods in Valencia, the revised Patricova planning rules ban underground garages in the highest flood-risk zones and strengthen sewers and pavements. The changes also include evacuation stairs on ground floors and elevators on upper floors in new buildings. The item focuses on risk-reduction and preparedness measures rather than on warnings issued during the event.", "title": "This is how it will be built after the DANA: shops with low occupancy, evacuation stairs on ground floors and elevators on upper floors", "wmo_regions": ["VI"]}');
